import 'package:ddcs_app/core/widgets/section_heading.dart';
import 'package:ddcs_app/models/customer_review.dart';
import 'package:flutter/material.dart';
class ReviewsSection extends StatelessWidget { const ReviewsSection({super.key,required this.reviews}); final Future<List<CustomerReview>>? reviews; @override Widget build(BuildContext context)=>Container(color:const Color(0xFFEEF4FA),padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const SectionHeading(eyebrow:'Customer stories',title:'Reviews built on trust',subtitle:'Published customer feedback from Supabase.'),const SizedBox(height:18),FutureBuilder<List<CustomerReview>>(future:reviews,builder:(context,snapshot){final rows=snapshot.data??const <CustomerReview>[];if(rows.isEmpty)return const Card(child:Padding(padding:EdgeInsets.all(18),child:Text('Customer reviews will appear here after they are added and approved.')));return Column(children:rows.map((r)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('★'*r.rating.clamp(1,5),style:const TextStyle(color:Color(0xFFF59E0B))),const SizedBox(height:8),Text('“${r.message}”'),const SizedBox(height:8),Text(r.name,style:const TextStyle(fontWeight:FontWeight.w800))])))).toList());})])); }
